select organisation_name, verification_status, regions
from public.alfik_lifeline_services
where lower(organisation_name) in (
  'raystede centre for animal welfare','cats protection lifeline','dogs trust freedom project',
  'rspca ashford & district','animal foodbank uk','rspca kent north west branch',
  'rspca kent west branch','rspca tunbridge wells & maidstone branch',
  'rspca kent-folkestone & district branch','lord whisky sanctuary fund',
  'misfits rescue kent','anim-mates','cats protection kent cat centre',
  'battersea brands hatch','foal farm animal rescue centre','the cinnamon trust'
)
order by organisation_name;
